  return $rows->where('return',false)->groupBy('sale_key')->map(function($lines,$key)use($known){$first=$lines->first();$products=[];$categories=[];foreach($lines as $r){if($r['product_id']){$id=$r['product_id'];$products[$id]??=['id'=>$id,'name'=>$r['product'],'unit'=>$r['unit'],'quantity'=>0,'value'=>'0.00'];$products[$id]['quantity']+=(float)$r['quantity'];$products[$id]['value']=Money::add($products[$id]['value'],$r['revenue']);}if($r['category_id'])$categories[$r['category_id']]=$r['category'];}
   return ['key'=>$key,'known_at'=>$known[$key]??null,'date'=>$first['date'],'customer_id'=>$first['customer_id'],'value'=>AnalyticsSalesLedger::sum($lines,'revenue'),'products'=>$products,'categories'=>$categories,'url'=>$first['url']];
