  usort($opportunities,fn($a,$b)=>[($a['kind']==='REORDER_OPPORTUNITY'?0:1),$a['window']['start']??'9999',-(float)($a['value_range'][1]??0)]<=>[($b['kind']==='REORDER_OPPORTUNITY'?0:1),$b['window']['start']??'9999',-(float)($b['value_range'][1]??0)]);
