  $identityKeys=[];foreach(Customer::get(['id','name','email','fiscal_number','business_registration_number']) as $identity)foreach(['name','email','fiscal_number','business_registration_number'] as $field){$normalized=mb_strtolower(preg_replace('/[\s\p{P}]+/u','',trim((string)$identity->$field)));if($normalized!=='')$identityKeys[$field.':'.$normalized][]=$identity->id;}$duplicateNames=count(array_filter($identityKeys,fn($ids)=>count(array_unique($ids))>1));if($duplicateNames)$health[]=['code'=>'possible_duplicate_identity','count'=>$duplicateNames,'detail'=>'Review matching names manually; AIMS does not merge identities.'];
