  $signal['inventory']=['available_to_promise'=>$available,'incoming'=>$stock['incoming']??0,'committed'=>$stock['committed_outgoing']??0,'incoming_schedule'=>$stock['incoming_schedule']??[],'shipments'=>$this->logistics[$p->id]??[],'constrained'=>$conflict,'qualification'=>'Current available-to-promise; incoming dates are not guarantees.'];$signal['decisions']=[$signal['kind']==='REORDER_OPPORTUNITY'?'REORDER_OPPORTUNITY':'RELATED_PRODUCT'];if($conflict)$signal['decisions'][]='SALES_INVENTORY_CONFLICT';
